<template>
  <div class="page-container ledger-page"><el-tabs v-model="activeTab"><el-tab-pane label="普通收储台账" name="ordinary"/><el-tab-pane label="受灾补充收储台账" name="supplement"/></el-tabs><DisasterWorkspace v-if="activeTab==='supplement'" initial-tab="executions"/><template v-else><header><div><h2>青贮生产/收储台账</h2><p>按整份备案记录填报实际执行信息，保留原申报的预计值。</p></div><el-button @click="load">刷新</el-button></header>
    <div class="panel"><el-form inline><el-form-item label="关键词"><el-input v-model="keyword" placeholder="收储主体或备案编号" clearable/></el-form-item></el-form><el-table :data="rows" border><el-table-column prop="filedNo" label="备案编号" min-width="240"/><el-table-column prop="storageSubjectName" label="收储主体" min-width="220"/><el-table-column label="申报面积（亩）" width="140"><template #default="{row}">{{ row.area.toFixed(1) }}</template></el-table-column><el-table-column prop="expectedYield" label="预计产量（吨）" width="145"/><el-table-column label="预计收储重量（吨）" width="165"><template #default="{row}">{{ row.weight ?? '未填' }}</template></el-table-column><el-table-column label="实际收储重量（吨）" width="165"><template #default="{row}">{{ execution(row.id)?.weight ?? '待填报' }}</template></el-table-column><el-table-column label="执行状态" width="110"><template #default="{row}">{{ execution(row.id)?.status || '待填报' }}</template></el-table-column><el-table-column label="操作" fixed="right" width="175"><template #default="{row}"><el-button link @click="openDetail(row)">原申报</el-button><el-button v-if="canWrite(row)" link type="primary" @click="edit(row)">填报实际</el-button><el-button v-else link @click="edit(row)">查看执行</el-button></template></el-table-column></el-table></div>
    <el-dialog v-model="detailVisible" title="原申报信息（预计值）" width="min(1050px,95vw)" top="4vh" destroy-on-close><div class="detail-scroll"><OrdinaryDetail :application="current"/></div></el-dialog>
    <el-dialog v-model="editVisible" title="实际执行信息" width="min(680px,95vw)"><p>{{ current?.filedNo }} · {{ current?.storageSubjectName }}</p><el-form label-position="top" :disabled="!canWrite(current)" class="execution-form"><el-form-item label="实际面积（亩）"><el-input-number v-model="form.actualArea" :min="0" :precision="1"/></el-form-item><el-form-item label="实际产量（吨）"><el-input-number v-model="form.actualYield" :min="0" :precision="2"/></el-form-item><el-form-item label="实际收储重量（吨）"><el-input-number v-model="form.weight" :min="0" :precision="2"/></el-form-item><el-form-item label="实际收储价格（元/吨）"><el-input-number v-model="form.price" :min="0" :precision="2"/></el-form-item><el-form-item label="实际收储时间"><el-date-picker v-model="form.storageTime" type="date" value-format="YYYY-MM-DD"/></el-form-item></el-form><template #footer><el-button @click="editVisible=false">关闭</el-button><template v-if="canWrite(current)"><el-button :disabled="saving" @click="save(false)">保存草稿</el-button><el-button type="primary" :loading="saving" @click="save(true)">保存执行信息</el-button></template></template></el-dialog>
  </template></div>
</template>
<script setup>
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { ElMessage } from 'element-plus'
import { useRoute } from 'vue-router'
import { useUserStore } from '@/stores/user'
import { fetchOrdinaryApplications,fetchOrdinaryLedgers,saveOrdinaryLedger,canSubmitOrdinary,isOrdinaryOwner } from '@/api/silOrdinary'
import OrdinaryDetail from '@/components/sil/OrdinaryDetail.vue'
import DisasterWorkspace from '@/components/sil/DisasterWorkspace.vue'
const activeTab=ref('ordinary')
const canWrite=app=>!!app&&canSubmitOrdinary(userStore.role)&&(isOrdinaryOwner(app,userStore.role)||(userStore.role?.storageSubjectId&&userStore.role.storageSubjectId===app.storageSubjectId))
const userStore=useUserStore();const route=useRoute();const applications=ref([]);const ledgers=ref([]);const keyword=ref('');const detailVisible=ref(false);const editVisible=ref(false);const saving=ref(false);const current=ref(null);const form=reactive({})
const rows=computed(()=>applications.value.filter(app=>app.status==='filed'&&(!keyword.value||`${app.filedNo} ${app.storageSubjectName}`.includes(keyword.value))))
const execution=id=>ledgers.value.find(item=>item.declarationId===id)
let openedQueryId=''
const load=async()=>{[applications.value,ledgers.value]=await Promise.all([fetchOrdinaryApplications(userStore.role),fetchOrdinaryLedgers(userStore.role)]);if(route.query.id && openedQueryId!==route.query.id){const app=rows.value.find(item=>item.id===route.query.id);if(app){openedQueryId=route.query.id;edit(app)}}}
const openDetail=app=>{current.value=app;detailVisible.value=true}
const edit=app=>{current.value=app;Object.keys(form).forEach(key=>delete form[key]);Object.assign(form,{declarationId:app.id,actualArea:null,actualYield:null,weight:null,price:null,storageTime:''},execution(app.id)||{});editVisible.value=true}
const save=async submit=>{if(submit&&(form.weight===null||form.weight===undefined||form.weight===''||Number(form.weight)<=0))return ElMessage.warning('提交执行信息时请填写大于0的实际收储重量');saving.value=true;try{const result=await saveOrdinaryLedger({...form,submit},userStore.role);if(!result.success)return ElMessage.error(result.message);ElMessage.success('实际执行信息已保存，原申报预计值保持不变');editVisible.value=false;await load()}catch{ElMessage.error('保存失败，请重试')}finally{saving.value=false}}
watch(()=>userStore.role?.code,()=>{editVisible.value=false;detailVisible.value=false;openedQueryId='';load()});onMounted(load)
</script>
<style scoped>.ledger-page{overflow:auto;gap:16px}header{display:flex;justify-content:space-between;align-items:center}h2{margin:0;font-size:22px}header p{font-size:13px;color:#667085}.execution-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.execution-form :deep(.el-input-number),.execution-form :deep(.el-date-editor){width:100%}.detail-scroll{max-height:75vh;overflow:auto}@media(max-width:600px){.execution-form{grid-template-columns:1fr}header{flex-wrap:wrap}}</style>
